out = []
for i in range(1290, len(src)):
    s = src[i]; t = s
    for a, b in R: t = re.sub(a, b, t)
    for a, b in GER.items(): t = re.sub(r'\b' + a + r'\b', b, t)
    for a, b in FIX: t = t.replace(a, b)
